import java.util.*;

public class Main {
    static long paint(int pos, int r, int c, int k, int[] cells) {
        if (pos == r * c) return 1;
        int row = pos / c, col = pos % c;
        long total = 0;
        for (int color = 0; color < k; color++) {
            if (col > 0 && cells[pos - 1] == color) continue;
            if (row > 0 && cells[pos - c] == color) continue;
            cells[pos] = color;
            total += paint(pos + 1, r, c, k, cells);
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long r = sc.nextLong();
        long c = sc.nextLong();
        long k = sc.nextLong();

        System.out.println(paint(0, (int) r, (int) c, (int) k, new int[(int) (r * c)]));
    }
}
